--[[
    Help text for the settings panel, lifted from config.lua.

    GENERATED — do not edit by hand. The wording lives in the comments above
    each setting in config.lua, so there is one place to keep true rather than
    a second copy that drifts.
]]

Config = Config or {}

Config.Descriptions = {
    ["Achievements"] = "Opened from the job panel, next to the guide. The species list is NOT written here: one entry is generated for every fish in Config.Fish, so add a fish and its achievement appears on its own. What is written here is everything that is not \"catch one of these\". id unique, and what the database stores. Renaming one makes every player lose that unlock, so pick it once. icon a Font Awesome name from the list in AchievementsView.jsx type totalCatches | speciesCount | trophies | released | heaviest value the number that has to be reached reward optional money paid once, when it unlocks experience optional experience paid once",
    ["Achievements.SpeciesReward"] = "Paid when a species achievement (the generated ones) unlocks.",
    ["AdminPanel"] = "One command and one screen. Everything in this file can be changed from it, and its Events tab opens a tournament or a golden zone and shows what is already running so you can stop it. A setting changed there is SAVED, not applied: it takes effect the next time the resource restarts, and the panel says so until it does. Swapping a table out from under code that is already using it is not a settings change. The permission is checked on the SERVER every time — on opening the panel and again on every button inside it. `command.fishing` is used as the ACE rather than a name of our own because nearly every server.cfg already carries `add_ace group.admin command allow`, which grants the whole `command.*` space. An existing admin can use this with nothing to configure.",
    ["AdminPanel.Ace"] = "Grant with: add_ace group.admin command.fishing allow",
    ["AdminPanel.ConfigCommand"] = "Chat command that opens it. '' removes the command.",
    ["Bait"] = "Bait gates nothing. You can fish with a bare hook, the wrong bait or the right one; what changes is how likely the fish you want becomes, never whether it is possible at all.",
    ["Bait.Favourite"] = "Weight multiplier for a fish whose favourite this is.",
    ["Bait.None"] = "What a bare hook is worth, for comparison. The baseline, so 1.",
    ["Bait.Other"] = "Weight multiplier for every OTHER fish while any bait is on the hook. Above 1 because a baited hook beats a bare one whatever is down there.",
    ["BiteTime"] = "Seconds the fish takes to bite after the cast. Level and line bonuses cut this down, to a floor of a second and a half.",
    ["BiteTime.max"] = "seconds",
    ["BiteTime.min"] = "seconds",
    ["Blip"] = "Blip sprites: https://docs.fivem.net/docs/game-references/blips/",
    ["BoatRental"] = "Depth decides what bites, and the deep water is out where you cannot wade — so without a boat the bottom half of the fish table is scenery. Rentals are per player and per session. There is no persistence: a boat is something you take out for an afternoon. Note for anyone adding perks to a tier: standing on a boat's DECK does not count as being in a vehicle, so a tier must never key off where the player is standing. Key it off the open rental instead.",
    ["BoatRental.Refund"] = "Metres from the dock you must bring a boat back to get the deposit, and the % of the price returned when you do.",
    ["BoatRental.ReturnRadius"] = "Metres from the dock you must bring a boat back to get the deposit, and the % of the price returned when you do.",
    ["BoatRental.ReturnTo"] = "Where a player is put down after handing a boat back.",
    ["BoatRental.Spawn"] = "Where a rented boat appears: x, y, z and the way it faces. Z is ignored — the water surface is found for you — so only x, y and the heading matter.",
    ["BoatRental.Tiers"] = "The boats on the shelf, in order. `minutes` is how long the rental lasts.",
    ["BoatRental.WarnBefore"] = "Seconds of warning before a rental runs out.",
    ["Campfire"] = "Burn some wood on the sand, thread a fish onto a skewer, hold it over the flames and keep turning it. Take it off at the right moment and you have a cooked skewer; leave it and you have a burnt one. It is the one thing you can do with a fish other than sell it, and the only activity here that needs something the water cannot give you: wood.",
    ["Campfire.BurnMinutes"] = "Minutes a fire burns, on the server's clock: it goes out at the same second for everybody, and anything still on it is handed back as it is.",
    ["Campfire.Command"] = "Chat command to build a fire. false leaves only the wood item.",
    ["Campfire.Confirm"] = "Ask before spending the wood. false builds on the click.",
    ["Campfire.Cook.Camera"] = "false cooks from the ordinary third-person view instead of swinging the camera onto the skewer. The mouse still turns the fish.",
    ["Campfire.Cook.Exclude"] = "Every fish in Config.Fish is cookable except the ones named here.",
    ["Campfire.Cook.Experience"] = "Experience for a skewer that came off the fire cooked. A burnt one pays nothing.",
    ["Campfire.Cook.ToBurnt"] = "Seconds OVER THE FIRE, not since you started: the clock only runs while the skewer is within HeatRange of the flames. Under ToCooked it is raw, between the two it is done, past ToBurnt it is charcoal. The cooking bar is drawn to scale from these two.",
    ["Campfire.Cook.ToCooked"] = "Seconds OVER THE FIRE, not since you started: the clock only runs while the skewer is within HeatRange of the flames. Under ToCooked it is raw, between the two it is done, past ToBurnt it is charcoal. The cooking bar is drawn to scale from these two.",
    ["Campfire.Food"] = "Hunger each skewer restores, as a % of the bar. Raw cannot be eaten. Only read off ox_inventory — under ox the same numbers live in the items' own client.status blocks. Edit both if you change one.",
    ["Campfire.Fuel"] = "What a fire costs: any ONE of these items, Amount of it. These three come from qs-lumberjack. Name an item your inventory does not have and nobody can light a fire (the console says so).",
    ["Campfire.Ground.NoWater"] = "No fires on water. Roads, concrete and indoor floors are always refused as well.",
    ["Campfire.Ground.Zones"] = "Your own no-build circles. `label` is shown in the refusal, so name them the way a player would say them out loud.",
    ["Campfire.Items"] = "The three items handed over; they already exist in the items files. Raw is both an outcome and an ingredient: it can go back over a fire.",
    ["Campfire.Limit"] = "Fires one player may have going, and metres between them. Anyone may cook on anyone's fire.",
    ["Campfire.Marker"] = "The marker over every fire, including other people's. Shapes: https://docs.fivem.net/docs/game-references/markers/",
    ["Cast"] = "Holding the cast key sweeps a power meter up and back down; letting go locks in whatever it was on. That power decides four things at once: · how far out the float lands · the odds of anything biting (Config.Depth.EmptyPowerRelief) · how big the fish is (Config.FishStats.CastBonus) · which fish are reachable at all (RarityPowerFactor below) Enabled = false goes back to one key press at full power.",
    ["Cast.MaxDistance"] = "Metres a cast covers at 0% and 100% power.",
    ["Cast.MinDistance"] = "Metres a cast covers at 0% and 100% power.",
    ["Cast.Splash"] = "particle where the bobber hits the water",
    ["CatchDecision"] = "Every landed fish is offered up before it goes in the bag. Releasing it hands back no item but pays more experience — the fish still counts for records and achievements either way, which is the whole point: a player chasing the biggest pike on the server does not have to fill their pockets to do it.",
    ["CatchDecision.KeepExperience"] = "Experience multipliers. Releasing pays more than keeping, and releasing a trophy pays more again — the fish you give up is the one worth points.",
    ["CatchDecision.ReleaseCountsForQuests"] = "true lets a released fish still count toward quests.",
    ["CatchDecision.ReleaseExperience"] = "Experience multipliers. Releasing pays more than keeping, and releasing a trophy pays more again — the fish you give up is the one worth points.",
    ["CatchDecision.Timeout"] = "ms before it decides for you, and what that decision is.",
    ["CatchDecision.TimeoutKeeps"] = "ms before it decides for you, and what that decision is.",
    ["CatchDecision.TrophyReleaseBonus"] = "Experience multipliers. Releasing pays more than keeping, and releasing a trophy pays more again — the fish you give up is the one worth points.",
    ["CatchModels"] = "The catch shot hangs a real ped off the rod, not a prop. `a_c_fish` stands in for everything; anything listed here overrides that for its own species. Only worth adding when the game has a model for the thing. Check it first with `/test <model>`: some peds hang wrong in the shot.",
    ["Clothing"] = "true to swap the player into the fisher outfit when going on duty. The outfit itself is defined at the top of client/clothing.lua.",
    ["CrabTraps"] = "Drop a cage in deep water, tie it to a buoy, come back later, pull it up full of crab. Passive fishing that runs while you do something else. Use the `crab_trap` item over deep enough water. The cage sinks, a buoy floats above it, and a blip goes on YOUR map so you can find it again. The soak is a curve, not a countdown. Yield GROWS the longer it sits, up to a cap, so \"how long do I leave it\" is a decision rather than a wait. Past the cap it stops accumulating and starts running down its clock toward breaking. Note: depth can only be measured on the client, so the server bounds the claim instead — the trap must be placed near the ped it can actually see, and the reported depth is clamped to a sane range.",
    ["CrabTraps.Blip"] = "The blip on each of your own traps.",
    ["CrabTraps.BreakChance"] = "% chance the trap is lost when you haul it, and when you dismantle it on purpose. Dismantling is the safer way to get it back.",
    ["CrabTraps.Decay"] = "Minutes before a forgotten trap breaks up, and how long before that it starts warning you.",
    ["CrabTraps.DismantleBreakChance"] = "% chance the trap is lost when you haul it, and when you dismantle it on purpose. Dismantling is the safer way to get it back.",
    ["CrabTraps.Experience"] = "Experience per trap hauled, and whether a trap inside a golden zone pays the hotspot bonus.",
    ["CrabTraps.HotspotBoost"] = "Experience per trap hauled, and whether a trap inside a golden zone pays the hotspot bonus.",
    ["CrabTraps.Limit"] = "Traps one player may have out: Base, plus one per PerLevel fisher levels, up to Max.",
    ["CrabTraps.Loot"] = "What a trap catches, per depth band. `weight` is relative, not a percentage.",
    ["CrabTraps.MinDepth"] = "Metres of water a trap needs. NoStructures refuses a drop under a pier or a bridge; RequireBoat forces you to be in one to place it.",
    ["CrabTraps.RequireBoat"] = "Metres of water a trap needs. NoStructures refuses a drop under a pier or a bridge; RequireBoat forces you to be in one to place it.",
    ["CrabTraps.Sell"] = "What the shop pays per crab.",
    ["CrabTraps.Soak"] = "How a trap fills. Minutes to a full catch, the fraction you still get from hauling one straight back up, and how the yield curves between the two (above 1 means most of the catch arrives late).",
    ["CurrencyPosition"] = "Where the currency symbol goes: \"prefix\" → $500, \"suffix\" → 500 zł",
    ["Debug"] = "Turn this on and the script explains what it is doing in the server console and in the client console (F8). Useful when something is not working and you want to see how far it got before it stopped. Leave it off on a live server: it prints a lot.",
    ["DefaultNotifications"] = "Notifications & money",
    ["Depth"] = "Depth is what decides who is down there — it replaced the old fresh/salt rule, which was invisible to the player standing in front of the water. The seabed is probed under the point the float will land and the depth is measured from the surface down. The prompt names it before you cast, so the one thing that decides what you might catch is the one thing you are shown. Deeper water holds rarer and bigger fish. Bands are read in order and the first one the depth falls under wins, so `max` has to climb. The last band catches everything deeper.",
    ["Depth.Bands"] = "The four depth bands, by metres of water. Every fish, net haul and crab trap picks its loot from the band it is in.",
    ["Depth.Base"] = "How deep you can fish: Base metres, plus PerLevel per fisher level and PerGearPoint per point of fitted gear.",
    ["Depth.EmptyWeight"] = "Weight of \"nothing bit\" against the fish list, and how much of the cast's power is refunded when that happens.",
    ["Depth.PerGearPoint"] = "How deep you can fish: Base metres, plus PerLevel per fisher level and PerGearPoint per point of fitted gear.",
    ["Depth.PerLevel"] = "How deep you can fish: Base metres, plus PerLevel per fisher level and PerGearPoint per point of fitted gear.",
    ["Depth.ShoreDepth"] = "Casting from the shore cannot reach past ShoreDepth metres, plus ShoreAllowance of slack so standing a step back does not change the band.",
    ["DrawText3D"] = "Show the on-screen \"press E to…\" prompts",
    ["EnableBlip"] = "true to show the job blip on the map",
    ["EnableLeaderboard"] = "Opened from the \"Statistics\" button in the job panel.",
    ["FightDifficulty"] = "Difficulty comes from the DEPTH, not from the rarity. Deep water is hostile because it is deep, so the species that live there can be common without any of them going soft — you should meet a swordfish often and lose to it often, rather than meet a boot three times and a swordfish once. Two inputs, added together and clamped to 1.0: Tiers the fish's OWN band. A swordfish fights like a swordfish wherever you hook it. WeightInfluence how much the individual specimen adds on top. A record fish is a harder fight than a runt of the same species. Enabled = false makes every fish fight the same, whatever it is and wherever it came from.",
    ["FightDifficulty.Tiers"] = "Base difficulty by band, 0 easiest and 1 hardest. These are the numbers to tune while you are feeling this out. Test any of them straight away with `/test3 <0..1>`, which runs a fight at that difficulty and nothing else — no bite wait, no fish, no reward.",
    ["Fish"] = "Each entry in `items` is read positionally: [1] item name the inventory item given [2] label what the UI shows [3] weight how common it is [4] max drop most that can come up at once [5] sell price what the shop pays per unit [6] experience XP per catch [7] home depth which band it lives in (Config.Depth) [8] favourite bait never a requirement, only better odds A cast is a raffle, not a ladder. Every fish gets [3] tickets, multiplied by how well the depth matches (Config.Depth.Match), whether your bait is its favourite (Config.Bait) and whether you cast hard enough (Config.Cast). One winner is drawn. An \"empty hook\" ticket is in the same draw (Config.Depth.EmptyWeight) and hands over Config.GarbageItem instead. So nothing here is a percentage: 98 against 40 means one fish is roughly two and a half times likelier ALL ELSE BEING EQUAL, and all else rarely is. [4] is a ceiling, not a promise: landing more than one is gated behind Config.MultiCatch.Chance first, then rolled across 2..max.",
    ["Fish.barracuda"] = "Deep and abyssal fish are NOT rare. Config.FightDifficulty reads the band, so a swordfish is punishing because of where it lives rather than because it is scarce. Fish where the monsters are and you will meet monsters. ── Deep",
    ["Fish.california_halibut"] = "Deep and abyssal fish are NOT rare. Config.FightDifficulty reads the band, so a swordfish is punishing because of where it lives rather than because it is scarce. Fish where the monsters are and you will meet monsters. ── Deep",
    ["Fish.lingcod"] = "Deep and abyssal fish are NOT rare. Config.FightDifficulty reads the band, so a swordfish is punishing because of where it lives rather than because it is scarce. Fish where the monsters are and you will meet monsters. ── Deep",
    ["Fish.shark"] = "The shark is here but no rod will ever land one: its weight is ZERO, so it gets no tickets in the draw. It is listed for its price, its label and its image — the speargun hands the species over directly, without a roll.",
    ["Fish.stingray"] = "Never in pairs, and the game has a ped for it, so a landed one hangs on the line as an actual ray. See Config.CatchModels.",
    ["Fish.swordfish"] = "Never in pairs, and the game has a ped for it, so a landed one hangs on the line as an actual ray. See Config.CatchModels.",
    ["Fish.white_seabass"] = "Deep and abyssal fish are NOT rare. Config.FightDifficulty reads the band, so a swordfish is punishing because of where it lives rather than because it is scarce. Fish where the monsters are and you will meet monsters. ── Deep",
    ["Fish.yellowtail"] = "Deep and abyssal fish are NOT rare. Config.FightDifficulty reads the band, so a swordfish is punishing because of where it lives rather than because it is scarce. Fish where the monsters are and you will meet monsters. ── Deep",
    ["FishParticles"] = "false removes the water splash while fighting a fish",
    ["FishSizes"] = "The lightest and heaviest a species ever gets, in kilograms. Every catch lands somewhere between the two. Anything not listed falls back to Config.FishStats.Default. Keep a range to about four times its own minimum. Real-world figures ruin the pricing: a tuna at 8 kg to 250 makes the biggest one thirty-one times the smallest, and one lucky cast pays for a week.",
    ["FishSizes.brown_crab"] = "Crab ── Pulled out of traps rather than caught on a rod, and weighed the same way so the shop prices them the same way. A trap crab carries its weight in metadata exactly as a fish does, which is what lets the sell panel group them and charge more for the big ones without a second system. The tiers are a real ladder: a yellow crab is roughly four times the common one at the same point in its range, on top of being far rarer.",
    ["FishSizes.crab"] = "Crab ── Pulled out of traps rather than caught on a rod, and weighed the same way so the shop prices them the same way. A trap crab carries its weight in metadata exactly as a fish does, which is what lets the sell panel group them and charge more for the big ones without a second system. The tiers are a real ladder: a yellow crab is roughly four times the common one at the same point in its range, on top of being far rarer.",
    ["FishSizes.striped_red_crab"] = "Crab ── Pulled out of traps rather than caught on a rod, and weighed the same way so the shop prices them the same way. A trap crab carries its weight in metadata exactly as a fish does, which is what lets the sell panel group them and charge more for the big ones without a second system. The tiers are a real ladder: a yellow crab is roughly four times the common one at the same point in its range, on top of being far rarer.",
    ["FishSizes.yellow_crab"] = "Crab ── Pulled out of traps rather than caught on a rod, and weighed the same way so the shop prices them the same way. A trap crab carries its weight in metadata exactly as a fish does, which is what lets the sell panel group them and charge more for the big ones without a second system. The tiers are a real ladder: a yellow crab is roughly four times the common one at the same point in its range, on top of being far rarer.",
    ["FishStats"] = "Every catch rolls one \"quality\" between 0 and 1 and the weight maps straight off it: a 90% fish sits 90% of the way up its species' range. quality = draw ^ (1 / (1 + bonus)) With no bonus that is a flat draw; every point of bonus bends it toward 1. Everything below feeds that one bonus. Turn Config.Debug on and each catch prints what it rolled and what fed into it.",
    ["FishStats.Default"] = "Size range in kg for a fish with no entry of its own in Config.FishSizes.",
    ["FishStats.Enabled"] = "false gives every fish the middle of its size range",
    ["FisherJob"] = "Jobs allowed to fish. Add as many as you need.",
    ["FishingAttachments"] = "The fishing animations live in client/fishing.lua, not here: they are part of how the job looks rather than something a server tunes, and keeping them in the escrowed side means a player cannot rewrite them. Rod attachments, grouped by the slot they fit into. bait consumed on every catch; each fish has a favourite hook fightEase — % off how hard the reel-in fights reel extraCatchChance — % chance to pull up one extra fish line biteTimeReduction — % off the wait before a bite Any slot can carry any bonus, and several at once — the four above are only how the stock catalogue is arranged. Every bonus the script understands: fightEase % off the difficulty of the reel-in. Capped by Config.FightDifficulty.MaxEase. extraCatchChance % chance to pull up one extra fish biteTimeReduction % off the wait before a bite specimenSize % push toward the big end of a species' size range. Not a trophy chance: it makes every fish run bigger, and bigger fish cross the trophy line more often. Each point is worth Config.FishStats.GearBonusPerPoint. lineStrength % more angle you can pull through before the line snaps rodDurability % off the rod's chance of breaking when you lose a fish baitSaver % chance a cast does not use up the bait `requiredLevel` gates both buying the item and fitting it.",
    ["FishingAttachments.hook"] = "Hooks lean on landing the fish: the crit that skips the fight, and how big what you hook runs.",
    ["FishingAttachments.line"] = "Lines govern the wait and the fight.",
    ["FishingAttachments.reel"] = "Reels are about how much you bring up, and keeping the rod in one piece.",
    ["FishingEquipment"] = "Everything listed here is what the shop sells. Prices and level locks are re-checked on the server, so this table is the only place to change them. The fish is the unit. One average fish sells for about 20 (the table runs 3 to 72, plus the shark at 150), and a decent session lands twenty or thirty of them — so a session is roughly 400 to 600. Every price below is a multiple of that. If you change what fish are worth, scale these with them or the whole economy tilts. The gear that is not a rod attachment. `wooden_rod` is the starter rod and the fallback: it is what the script assumes a player is holding when none of the rod tiers below are in their bag. The tackle box opens the attachment screen. Everything here shows in the shop's EQUIPMENT tab. `requiredLevel` is optional and defaults to 1; `image` is optional too, and only worth setting when the artwork is not named after the item. The shop's gear shelf. `requiredLevel` hides a row until the player gets there; leave it out to sell from level 1. Rod attachments have their own table further down (Config.FishingAttachments).",
    ["FishingNets"] = "The third way to fish, and a different verb from the other two: rod aim stand still, time the strike, fight one fish trap wait pick a spot, leave, come back net drive the boat IS the tool Use a net while sitting in a boat rented from the job ped. It streams off the stern and fills by DISTANCE SAILED, not by time, so a net only pays while the boat is moving at a sensible speed over deep enough water.",
    ["FishingNets.BreakLosesNet"] = "true loses the net item when it tears; false hands it back damaged.",
    ["FishingNets.Experience"] = "Experience per haul, and whether trawling through a golden zone pays the hotspot bonus.",
    ["FishingNets.HotspotBoost"] = "Experience per haul, and whether trawling through a golden zone pays the hotspot bonus.",
    ["FishingNets.Loot"] = "What a haul contains, per depth band. `weight` is relative, not a percentage.",
    ["FishingNets.MinDepth"] = "Metres of water needed before a net may go out.",
    ["FishingNets.Tiers"] = "The three nets, in order. A net is used from the helm of a rented boat and trawls behind it while you drive; fish accumulate by the metre.",
    ["FishingRodBreakChance"] = "% chance the rod breaks when you lose a fish",
    ["FishingRodWithdrawAnimation"] = "true to play a short animation when the rod is taken out or put away",
    ["FoodBoat"] = "A grill boat you carry in your bag and set down on dry LAND — the Málaga sardine grills are old fishing boats filled with sand and dragged up the beach, and that is this. Use the item: the screen fades, the boat lands in front of you and you come back standing behind the counter. Every raw skewer in your bag appears on the rack beside you. Drag one onto the coals, turn it before that side chars, turn it back, and take it off cooked — or leave it and take it off charcoal. The interact key swaps between two views: over the counter looking out, and straight down at the grill. Only the second lets you drag, because only the second lets you see what you are dragging onto. Positions, cameras and layouts are in client/foodboat.lua. `/boat1` to `/boat9` tune them live and print what they land on.",
    ["FoodBoat.Burnt"] = "What goes on the coals and what comes off them. The same three items a campfire produces, so a skewer is a skewer wherever it was cooked.",
    ["FoodBoat.Cook"] = "Seconds per side. Side is how long one side needs over the coals; Burn is how long it survives before charring, so the gap between them is your window to turn it. A skewer is done when BOTH sides have had their time, and char either side and it comes off burnt.",
    ["FoodBoat.Cooked"] = "What goes on the coals and what comes off them. The same three items a campfire produces, so a skewer is a skewer wherever it was cooked.",
    ["FoodBoat.Duration"] = "Seconds the boat stays out before packing itself up. 0 leaves it out until you pack it up or walk away.",
    ["FoodBoat.Grill"] = "How many skewers fit on the coals at once. This IS the difficulty: more slots means more fish to turn before they char.",
    ["FoodBoat.Item"] = "Bought in the shop and never consumed: setting the boat down keeps the item, and packing up hands it back.",
    ["FoodBoat.Keys"] = "Interact swaps between the counter and the coals; Leave packs up. They are deliberately different keys: a mistimed press should cost you a camera move, not your whole stall.",
    ["FoodBoat.Keys.Grab"] = "LEFT MOUSE, drag and turn",
    ["FoodBoat.Keys.Interact"] = "E",
    ["FoodBoat.Keys.Leave"] = "BACKSPACE",
    ["FoodBoat.Particles"] = "The wisp of smoke under each skewer on the coals. Cosmetic only.",
    ["FoodBoat.Place"] = "Metres you may walk from the boat before it packs itself up. Generous: this is a stall, and walking round it is expected.",
    ["FoodBoat.Queue"] = "Customers walk up, ask for a number of skewers and pay for what they get. Drag a COOKED skewer onto one to hand it over. Short of what they wanted they still take what there is; if the stall is empty they pay and the whole thing packs up.",
    ["FoodBoat.Queue.Every"] = "Seconds between arrivals, picked between the two. This is the pace of the whole activity: short and the coals never catch up, long and you stand watching fish cook.",
    ["FoodBoat.Queue.Max"] = "How many may be waiting at once, and how many skewers one wants.",
    ["FoodBoat.Queue.Patience"] = "Seconds one waits before giving up and walking off, keeping (and having paid for) anything already handed over. 0 waits forever.",
    ["FoodBoat.Queue.Pay"] = "What one skewer pays. Charged per skewer HANDED OVER, so somebody who got half an order pays for half.",
    ["FoodBoat.Queue.Wants"] = "How many may be waiting at once, and how many skewers one wants.",
    ["FoodBoat.Raw"] = "What goes on the coals and what comes off them. The same three items a campfire produces, so a skewer is a skewer wherever it was cooked.",
    ["FoodBoat.Sound"] = "The sizzle when a skewer goes down, played at the boat so it falls away with distance. Quiet on purpose: it happens several times a minute.",
    ["GarbageItem"] = "Given instead of a fish when the cast rolls badly. It is sellable too, so it has to appear in Config.GarbagePrice below.",
    ["GarbagePrice"] = "What the shop pays for the junk item",
    ["Hotspots"] = "Every so often a stretch of open water starts fishing far better than usual. A gold star lands on every fisher's map and anyone casting inside the circle sees the difference while it lasts. Unlike a tournament there is no ranking and nobody loses — turning up is the whole of it. It is what gives the water a reason to move. Keep every zone somewhere you need a boat to reach, or at minimum a pier. A zone you can walk to is a zone everybody stands in. It does not hand out fish: the odds are tilted, blanks are rarer and the good species come up more often, but a bad cast is still a bad cast.",
    ["Hotspots.Boost"] = "What the zone is worth: EmptyChance is the % of the \"nothing bit\" weight removed, Rarity multiplies the odds on the rare fish, and MultiCatch multiplies the chance of pulling up more than one.",
    ["Hotspots.Duration"] = "Minutes a golden zone lasts.",
    ["Hotspots.FishersOnly"] = "true limits the bonus to players holding a fisher job.",
    ["Hotspots.Random"] = "Minutes between one closing and the next opening, picked between the two.",
    ["Hotspots.Zones"] = "Where they open. One is picked at random each time.",
    ["InventoryMetadata"] = "True when the running inventory can attach a weight to a single fish.",
    ["InviteDistance"] = "Metres someone must be within to be invited into the crew. Checked on the server, so a modified client cannot skip it. 0 turns the check off. It also keeps the crew tiles showing faces: the panel photographs each member's ped, and a ped only exists on your machine while its player is near you. Raise this past the streaming range and distant members fall back to their initials.",
    ["Keys"] = "Control IDs: https://docs.fivem.net/docs/game-references/controls/",
    ["Keys.AnchorKey"] = "Anchor a rented boat. Its own key because the interact key is already offering to cast a line when you are stood on a boat over water.",
    ["Keys.AnchorKeyLabel"] = "Anchor a rented boat. Its own key because the interact key is already offering to cast a line when you are stood on a boat over water.",
    ["Keys.DismantleKey"] = "Pack a crab trap away without emptying it. Its own key because the interact key at a buoy already offers to HAUL the trap up, and the two have different odds of breaking the cage. Only offered on a trap you own.",
    ["Keys.DismantleKeyLabel"] = "Pack a crab trap away without emptying it. Its own key because the interact key at a buoy already offers to HAUL the trap up, and the two have different odds of breaking the cage. Only offered on a trap you own.",
    ["Keys.InteractKey"] = "\"E\" — talk to the ped, cast the rod and strike on a bite",
    ["Keys.InteractKeyLabel"] = "What that key is CALLED, for prompts that spell it out. The game gives no way to turn a control id into a label, so if you change the id above, change this to match or the prompts will name the wrong key.",
    ["LeaderBoardRewards"] = "Money paid to the top 3 when each ranking resets.",
    ["LeaderBoardRewards.Daily"] = "Resets every day at 00:00 server time",
    ["LeaderBoardRewards.Daily.1"] = "1st place",
    ["LeaderBoardRewards.Daily.2"] = "2nd place",
    ["LeaderBoardRewards.Daily.3"] = "3rd place",
    ["LeaderBoardRewards.Season"] = "Resets at 00:00 on the first day of every month",
    ["LevelExperience"] = "What a level is worth, and what the next one costs. The first three are perks that stack per level up to Config.MaxBonusLevel; the last two set the curve.",
    ["LevelExperience.BaseExperience"] = "Experience required for level 1",
    ["LevelExperience.BiteTimeReduction"] = "% taken off the bite wait per level",
    ["LevelExperience.ExtraCatchChance"] = "% added to the bonus-fish chance per level",
    ["LevelExperience.FightEase"] = "% off the reel-in difficulty per level",
    ["LevelExperience.GrowthFactor"] = "How much more each level needs (endless levelling)",
    ["MaxBonusLevel"] = "Highest level the perks above keep scaling to. Without a cap a long-lived character eventually reaches 100% instant catches and the minigame stops happening at all. Levelling itself is not capped, only the bonuses.",
    ["MaxLeaderboardPlayers"] = "How many fishers each leaderboard tab shows. The database query is limited to this number, so raising it costs query time on every refresh.",
    ["MaxPartyMembers"] = "Crew size, including the leader",
    ["MaxShopPurchase"] = "Highest quantity the shop lets a player buy in one go, per item.",
    ["MissionPayout"] = "'members' every member gets the mission's full money and experience. A crew of four on a mission paying 2000 costs the server 8000. 'split' the money and the experience are divided between the members present when it completes. That same mission pays 500 each. Worth knowing before choosing: `fishAmount` does NOT scale with crew size, so four players bring in the same ten fish one player would. On 'members' that is four times the pay for the same work, which is the generous setting and the one this ships with so an existing server's economy does not move. Shares round DOWN and never fall below 1, so a small reward split many ways still pays something rather than reading as a bug. Anyone who left before it completed is already out of the crew and does not dilute the share.",
    ["MultiCatch"] = "How often a single cast lands more than one fish. One fish is the rule and more than one is an event: `Chance` per cent of successful casts roll again across 2..maxDrop, and everything else lands exactly one however generous the species' maxDrop is. At 4 that is roughly one cast in twenty-five, and only for species that could drop more than one to begin with.",
    ["PedGreeting"] = "Who the panel says you are talking to, and the line they greet you with. Both are shown on the card beside the ped while the interface is open. Leave either empty to hide that part of the card.",
    ["PedMarker"] = "The floating marker that shows players who to talk to.",
    ["PedMarker.bob"] = "Makes it drift gently up and down",
    ["PedMarker.color"] = "The colour, as red / green / blue, plus how see-through it is (a). All four go from 0 to 255.",
    ["PedMarker.distance"] = "How close you have to be to see it, in metres",
    ["PedMarker.enabled"] = "false hides it completely",
    ["PedMarker.height"] = "How high above the NPC's head it floats, in metres",
    ["PedMarker.size"] = "How big it is. Bigger numbers, bigger marker.",
    ["PedMarker.type"] = "The shape. 0 is the upside-down cone, the usual one for \"talk to this person\". The full list of shapes is here: https://docs.fivem.net/docs/game-references/markers/",
    ["PedName"] = "Who the panel says you are talking to, and the line they greet you with. Both are shown on the card beside the ped while the interface is open. Leave either empty to hide that part of the card.",
    ["PlayerNameSource"] = "Interface ─────────────────────────────────────────────────────────────── Which name the panel shows for a player. 'character' → the character's first and last name, read from your framework 'cfx' → the FiveM display name (the Steam / CFX account name) 'both' → \"Character Name (FiveM Name)\" The FiveM name is the fallback whenever the framework has no character name to give, so a slot is never left blank.",
    ["PoundsPerKilo"] = "One kilogram in pounds, for that conversion. Here rather than buried in the interface so the two sides cannot disagree about it.",
    ["QuasarInventory"] = "Inventory & clothing ──────────────────────────────────────────────────── true if you run qs-inventory: it locks the inventory during the outfit change",
    ["QuasarInventoryQuests"] = "true to hook into the qs-inventory quest system. It creates the fisher quests when a player loads and reports progress as they play. Needs qs-inventory running; leave it false if you do not use its quests.",
    ["RegisterUsableItemsManually"] = "Leave this off. Usable items are registered automatically for every inventory except ox_inventory, which dispatches its own from items_ox.lua. Turn it on only to force registration on top of ox.",
    ["RequireJob"] = "Who can fish",
    ["RodTiers"] = "A better rod buys more slots and a bigger bonus to everything fitted to it, and costs a higher chance of snapping when you lose a fish. The rod that lands trophies is also the rod you are most likely to break. item the inventory item. Must exist in your inventory. label shown in the shop and the tackle box requiredLevel gates buying it AND using it price shop price slots how many of the four slots it carries. They fill in order; the rest show locked with the rod that would unlock them. bonusScale multiplier on every attachment fitted to it. 1.0 is face value, 1.5 is half again. breakChance % chance of snapping when a fish is lost. Overrides Config.FishingRodBreakChance for this rod. perks flat bonuses the rod itself carries, on top of anything fitted. Same keys as attachment bonuses. Order matters: keep them worst to best. The best rod the player owns is the one they are using. `image` is the shop icon, from web/public/images/. `palette` is which of the five colour schemes in web/src/components/rodModel.js the 3D rod in the tackle box is painted with, so the rod on screen is the rod you are actually holding.",
    ["Speargun"] = "The only way to fish that you do IN the water, and it takes sharks and nothing else. No rod lands one and no net scoops one, which is the whole reason the system exists — a third way to catch the same fish would be a reskin. Sharks only exist while a hunt is accepted. No hunt, no sharks, anywhere: that is what keeps them an event instead of scenery, and it means no spawn loop runs for divers who are not hunting. Air is optional. See Breath below — the tank buys comfort, not access.",
    ["Speargun.Ammo"] = "one is consumed per shot",
    ["Speargun.Breath"] = "AIR. Our tank is deliberately not called `diving_gear`: that name belongs to another resource, and an inventory item has exactly one owner. The tank is a SUPPLY, not a longer breath. Underwater it drains a second per second and a gauge counts it down; on the surface it refills at Regen per second. While there is air left you cannot drown, and the moment it runs dry the game takes over and drowns you on its own clock. With no tank you have GTA's own lungs, about forty seconds. The hunt zones are placed so that is tight but possible. Shop decides whether it is on the fishing shop's shelf, never whether the item works: 'auto' hidden while ExternalResource is running, shown when it is not 'always' always sold here 'never' never sold here",
    ["Speargun.Harvest"] = "what a speared shark gives you",
    ["Speargun.Hunt"] = "THE HUNT. Accepted like any other job task — it is a row in Config.Tasks with a `hunt` block on it. A zone is drawn at random per hunt. CHECK THESE ON YOUR OWN MAP: they are open water on a stock map, but a map replacement can put land under one, and a shark hunt on a hillside is a shark hunt nobody can finish.",
    ["Speargun.Hunt.Alive"] = "Sharks alive at once, milliseconds before a dead one is replaced, and the depth band they swim in.",
    ["Speargun.Hunt.Marker"] = "A ring on the water over the hunt zone. Leaving size x/y nil draws it at the zone radius, so the marker IS the zone.",
    ["Speargun.Item"] = "the gun",
    ["Speargun.LoseGunOnDeath"] = "true takes the gun off you when a shark kills you.",
    ["Speargun.Range"] = "Metres a shot carries, and milliseconds to reload between shots.",
    ["Speargun.RecoverChance"] = "Every shot costs a spear. A miss is gone for good; on a hit, this is the % chance the shaft is still good when you cut the shark loose. Seconds is how long a missed spear stays stuck in the sea bed before it is cleaned up.",
    ["Speargun.RequiredLevel"] = "Late-game on purpose: the gun is expensive, sharks are the top of the price table, and the hunt asks you to swim into deep water on limited air.",
    ["Speargun.SharkMarker"] = "The marker over a shark. Underwater a carcass on a dark sea bed is nearly invisible. LiveSharks marks the living ones too, which does hand the player the hunt — set it false to mark only what you have already hit.",
    ["Speargun.Sharks.AttackChance"] = "% chance a shark that noticed you actually attacks. 0 means nothing ever bites: they still notice and close, they just do not commit. Rolled once per shark and remembered.",
    ["Speargun.Sharks.Temperaments"] = "Every shark draws a mood on spawn and you cannot tell which by looking. Relative weights, not percentages. aggressive comes at you once it notices you skittish leaves the moment it notices you indifferent ignores you until you shoot",
    ["Speargun.Sound"] = "The shot, played through xsound at the shooter so it fades with distance. Does nothing without xsound running.",
    ["Speargun.Tank"] = "optional air, see Breath",
    ["StartJob"] = "The one remaining ped. Talking to it opens the whole interface: missions, crew, statistics and the shop.",
    ["StartJob.ped"] = "The NPC who hands out the job. `coords` is x, y, z and the way he faces. noFishingRadius keeps people from casting on top of him.",
    ["Target"] = "How players interact",
    ["TargetScript"] = "Target resource: \"ox\" or \"qb\"",
    ["Tasks"] = "The missions players pick from the job panel. `fishAmount` and `fishRequired` are read in pairs: the first amount belongs to the first fish, and so on.",
    ["Tasks.description"] = "Do not touch",
    ["Tasks.experience"] = "Do not touch",
