    ["Tournaments"] = "The Guide screen in the job panel. It sweeps the map, measures the water it finds and marks it by depth band, so players can see what lives where and where water of each depth actually is.",
    ["Tournaments.AnnounceBefore"] = "Minutes one runs for, and how many minutes ahead it is announced.",
    ["Tournaments.Duration"] = "Minutes one runs for, and how many minutes ahead it is announced.",
    ["Tournaments.FishersOnly"] = "true limits entry to players holding a fisher job.",
    ["Tournaments.MinimumEntries"] = "Entrants needed before prizes are paid at all.",
    ["Tournaments.Prizes"] = "Payouts for 1st, 2nd and 3rd in each category: the single heaviest fish, and the most fish landed.",
    ["Tournaments.Random"] = "Unscheduled ones: every CheckEvery minutes, roll Chance % to open one.",
    ["Tournaments.ShowResults"] = "Show the final scoreboard to the players who fished the tournament. Winners are announced by notification either way.",
    ["Tournaments.Schedule"] = "Server time a tournament starts, every day. Leave empty for none.",
    ["Tournaments.Zones"] = "Where they run. One is picked at random each time.",
    ["UpdateLeaderboard"] = "Minutes between refreshes",
    ["WaterGuide"] = "The Guide button on the job panel: how the job works, read in game rather than on your Discord. It can also drop the tournament zones on the map.",
    ["WaterGuide.Blips"] = "let players put the tournament zones on their map",
    ["WaterGuide.Enabled"] = "false hides the Guide button entirely",
    ["Webhooks"] = "Off by default. Paste a webhook URL into `Url`, set Enabled to true, and switch on the events you care about. Each event takes one of three values: true send it, to the shared Url above false do not send it \"https://…\" send it to a channel of its own That last one is the useful one: money and experience can go to a staff channel while missions go somewhere everybody can see.",
    ["Webhooks.Avatar"] = "How the bot presents itself. Avatar takes an image URL, or '' for none.",
    ["Webhooks.Events.ConfigChanged"] = "An admin changed a setting from the panel. Worth keeping on: it is the audit trail for who moved what.",
    ["Webhooks.Events.ExperienceGiven"] = "Experience granted, with the level before and after.",
    ["Webhooks.Events.MissionAbandoned"] = "Abandoned from the panel, or left behind by disconnecting.",
    ["Webhooks.Events.MissionFinished"] = "The mission's fish are all in and it pays out.",
    ["Webhooks.Events.MissionStarted"] = "A player (or a crew leader) takes a mission from the panel.",
    ["Webhooks.Events.MoneyPaid"] = "Money handed to a player: a mission payout or a sale at the shop.",
    ["Webhooks.Name"] = "How the bot presents itself. Avatar takes an image URL, or '' for none.",
    ["Webhooks.Timestamp"] = "How the bot presents itself. Avatar takes an image URL, or '' for none.",
    ["WeightPricing"] = "The sell price in Config.Fish is what an AVERAGE specimen fetches; what you get scales with how heavy the one you landed was. The multiplier runs from Min at the bottom of a species' weight range to Max at the top. Set both to 1.0 for a flat price per species.",
    ["WeightPricing.Percent"] = "How much more a fish is worth per extra \"unit\" of its own minimum weight, as a percentage: price = base * (1 + (weight / minWeight - 1) * Percent / 100) The unit is the species' own lightest weight, not a kilogram — which is what lets one number work for a sardine and a swordfish at once. Doubling a fish always pays the same, whatever doubling means for that species.",
    ["WeightUnit"] = "'kg' or 'lb'. Display only: sizes, records and prices are kilograms internally, so switching this cannot change what a fish is worth.",
}
